{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Linezolid, the closest oxazolidinone analogue, showed an absolute oral bioavailability of 0.884 in elderly hospitalized patients and is reported as near-complete in other human studies; the query shares the oxazolidinone core and N-aryl morpholine motif, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Suvorexant had a mean absolute bioavailability of 82% under fasted conditions in humans, demonstrating that a moderately lipophilic heteroaromatic amide/piperazine drug can achieve high oral F; supportive for the query under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Flecainide absolute bioavailability averaged 70% (range 60-86%) in healthy subjects, supporting high F for an amide-containing aromatic drug with moderate lipophilicity and a basic center.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Asciminib has an absolute bioavailability of approximately 73% in humans, supporting high F for a drug with amide and heteroaromatic/piperazine-like features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Lurasidone has only about 10% oral bioavailability in the fasted state, but this low F is attributed to extensive first-pass metabolism and its structure is not an oxazolidinone; it is a contradictory outlier outweighed by the direct oxazolidinone analogue.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F >= 20%) because the query is a close oxazolidinone analogue of linezolid, whose absolute oral bioavailability is ~88-100% in humans, and numerous other transferable analogues show F > 50%. The only low-F analogue, lurasidone, is structurally distant and its low bioavailability reflects first-pass metabolism not expected for this oxazolidinone scaffold.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule; prediction relies on analogue transfer.",
    "Fasted-state-specific data for the closest analogue linezolid are not explicitly reported in the cited record, though linezolid F is high regardless of prandial state.",
    "The query's morpholin-3-one and 5-chlorothiophene-2-carboxamide substituents could alter first-pass metabolism or permeability relative to linezolid, but no experimental data address this."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

